body.script:
// Data for each trail, lift, and facility. This will be programmatically generated.
const trailData = {
    'timberwolf-trail_00000165211796375202709210000010540445799561181585_': {
        name: 'Timberwolf Trail',
        difficulty: 'easy',
        type: 'trail',
        status: 'Open',
        description: 'Your gentle path down the mountain. A favorite for all levels, Timberwolf Trail winds its way down from the top of the mountain, offering stunning scenery and a smooth, relaxing descent. Skiers right after the big turn, you\'ll find access to the Little Beaver beginner area, making Timberwolf an excellent option for families and groups of varying abilities.'
    },
    'sleepy-hollow': {
        name: 'Sleepy Hollow',
        difficulty: 'easy',
        type: 'trail',
        status: 'Open',
        description: 'Sleepy Hollow is Mount Kato\'s longest and easiest trail, offering a leisurely and scenic descent for skiers and snowboarders of all levels. This gentle, winding trail meanders through a picturesque wooded landscape, with wide, well-groomed slopes and minimal elevation changes. Whether you\'re a beginner finding your snow legs or a seasoned enthusiast seeking a relaxing run, Sleepy Hollow provides a tranquil and enjoyable experience for everyone.'
    },
    'birch-pass': {
        name: 'Birch Pass',
        difficulty: 'easy',
        type: 'trail',
        status: 'Open',
        description: 'Birch Pass is a short, beginner-friendly connecting trail linking the top of lift 6 to Birch Coulee. This well-groomed path is ideal for those seeking a relaxing glide through a scenic wooded landscape.'
    },
    'birch-coulee': {
        name: 'Birch Coulee',
        difficulty: 'medium',
        type: 'trail',
        status: 'Open',
        description: 'Birch Coulee is a wide, gentle slope perfect for beginner skiers and snowboarders to practice their skills and build confidence. This well-groomed trail offers a relaxing descent through a scenic birch forest, with ample space to turn and control your speed. It\'s a great place to enjoy the valley views and take in the fresh air while honing your abilities on the snow.'
    },
    'little-beave': {
        name: 'Little Beaver',
        difficulty: 'easy',
        type: 'trail',
        status: 'Open',
        description: 'Little Beaver Learning Area: Your perfect starting point on the slopes. Designed with beginners in mind, Little Beaver is a gentle, wide run offering a safe and fun environment to learn and practice skiing or snowboarding. Serviced by Lift Four, the dedicated learning area also features the SunKid conveyor lift for easy access, and is home to most beginner lessons. With its gradual slope and supportive atmosphere, Little Beaver is the ideal place to build confidence and develop your skills.'
    },
    'little-crow': {
        name: 'Little Crow',
        difficulty: 'medium',
        type: 'trail',
        status: 'Open',
        description: 'Little Crow is the easiest way down from lift seven, offering a gentle and wide path for intermediate skiers and snowboarders. This well-groomed trail features a gradual descent with minimal elevation changes, allowing for a relaxed and enjoyable glide through a scenic wooded landscape. Whether you\'re practicing your skills or simply prefer a slower pace, Little Crow provides a welcoming and stress-free experience for everyone.'
    },
    'big-hawk-ridge': {
        name: 'Big Hawk Ridge',
        difficulty: 'medium',
        type: 'trail',
        status: 'Open',
        description: 'Big Hawk Ridge: A scenic cruise with breathtaking views. This popular intermediate trail is a favorite among Mount Kato guests for its gentle slopes and stunning vistas of the Blue Earth River Valley. A perfect choice for those looking to enjoy a relaxing run while taking in the beauty of the surrounding landscape.'
    },
    'little-forest': {
        name: 'Little Forest',
        difficulty: 'medium',
        type: 'trail',
        status: 'Open',
        description: 'Little Forest: Offering intermediate skiers a delightful experience with its rolling terrain and scenic views. As you descend, you\'ll encounter gentle slopes and moderate pitches, perfect for practicing your turns and building confidence. Whether you\'re cruising down the slopes or hitting the park, Little Forest is sure to leave you smiling.'
    },
    'sleepy-creek-cutoff': {
        name: 'Sleepy Creek Cutoff',
        difficulty: 'medium',
        type: 'trail',
        status: 'Open',
        description: 'Sleepy Creek Cutoff offers intermediate skiers a scenic and enjoyable descent from the top of lift six. Whether you\'re looking for a quick run or a longer journey, Sleepy Creek Cutoff is a great addition to your Mount Kato experience.'
    },
    'wild-deer_00000111175242014020337350000005314294622917763735_': {
        name: 'Wild Deer',
        difficulty: 'medium',
        type: 'trail',
        status: 'Open',
        description: 'Wild Deer: An intermediate trail that takes it up a notch. A bit steeper than most blue runs at Mount Kato, Wild Deer is the perfect stepping stone for intermediate skiers ready to challenge themselves. Enjoy the thrill of a slightly steeper descent while still feeling confident on familiar terrain.'
    },
    'eagle-ridge_00000105411912884984635460000000851272969317083542_': {
        name: 'Eagle Ridge',
        difficulty: 'medium',
        type: 'trail',
        status: 'Open',
        description: 'Eagle Ridge: An intermediate trail with a hidden surprise. Similar to Wild Deer, Eagle Ridge offers a slightly steeper challenge than other blue runs at Mount Kato. Stay skiers left for a more gradual descent, or test your skills on the short, steep section right in the middle for an extra thrill. This versatile trail offers options for intermediates looking to push their limits.'
    },
    'sundance_00000123423080703862362750000018395771185093280954_': {
        name: 'Sundance',
        difficulty: 'medium',
        type: 'trail',
        status: 'Open',
        description: 'Sundance Terrain Park: Show off your freestyle skills on our premier park trail. This popular spot boasts a variety of features for all levels, but can get quite busy. If you\'re new to terrain parks or prefer a more relaxed experience, we recommend exploring our smaller progression parks, usually located at the top of Sleepy Hollow and/or Birch Coulee. Please note that rental equipment is prohibited in all terrain parks.'
    },
    'wolf-ridge_00000012461332066008056230000013452901512709310848_': {
        name: 'Wolf Ridge',
        difficulty: 'medium',
        type: 'trail',
        status: 'Open',
        description: 'Wolf Ridge: Test your limits on this thrilling intermediate run. Known for its challenging race course, Wolf Ridge is a fast, exciting descent that will get your heart pumping.'
    },
    'wolf-chute_00000086654002596323647540000008348298261282703253_': {
        name: 'Wolf Chute',
        difficulty: 'hard',
        type: 'trail',
        status: 'Open',
        description: 'Wolf Chute: Short, steep, and exhilarating. This narrow chute offers a quick shot of adrenaline for thrill-seekers. Be prepared for a challenging descent that will put your skills to the test.'
    },
    'big-brave_00000120557085615029559250000003498223768255235244_': {
        name: 'Big Brave',
        difficulty: 'hard',
        type: 'trail',
        status: 'Open',
        description: 'Big Brave: A thrilling challenge for the fearless. This steep run, accessible from Lifts One, Two, and Three at Mount Kato, is a favorite among those who crave adrenaline. Navigate the exhilarating terrain and test your skills on one of Mount Kato\'s most exciting descents.'
    },
    'brave-chute_00000162324572142955322400000008528502739943837625_': {
        name: 'Brave Chute',
        difficulty: 'hard',
        type: 'trail',
        status: 'Open',
        description: 'Brave Chute: Tucked between the trees and Lift Two, this steep, adrenaline-pumping chute is a favorite among Mount Kato\'s thrill-seekers. Test your skills and show off your advanced abilities on this challenging descent.'
    },
    'little-brave_00000053518113907445259450000017414086792017273220_': {
        name: 'Little Brave',
        difficulty: 'hard',
        type: 'trail',
        status: 'Open',
        description: 'Little Brave: A hidden gem for the fearless. Tucked under Lift One, Little Brave is a steep and fast trail that challenges even the most experienced skiers and snowboarders. This hidden gem is a local favorite, especially after a fresh snowfall.'
    },
    'tommahawk-chute': {
        name: 'Tommahawk Chute',
        difficulty: 'hard',
        type: 'trail',
        status: 'Open',
        description: 'An expert-only trail that delivers a thrilling rush of adrenaline. This steep, narrow chute plunges down from Big Bear, demanding precise control and confidence. This exhilarating trail is not for the faint of heart and should only be attempted by experienced skiers and snowboarders seeking a true test of their skills.'
    },
    'big-bear': {
        name: 'Big Bear',
        difficulty: 'hard',
        type: 'trail',
        status: 'Open',
        description: 'Big Bear, accessed by Lift Seven, is an exhilarating advanced run that challenges skiers and snowboarders with its steep pitches and varied terrain. This thrilling trail winds through a mix of open slopes and tree-lined sections, demanding precise turns and confident control. As you descend, you\'ll be rewarded with breathtaking views of the surrounding landscape. Big Bear is a must-try for experienced thrill-seekers looking to push their limits and conquer a demanding yet rewarding run.'
    },
    'lift-1': {
        name: 'Lift One',
        type: 'lift',
        status: 'Open',
        description: 'Your gateway to our front side trails, backside access, and the main terrain park on Sundance. This two-seater is the quickest route to the park and offers stunning views. For an easy descent from the top, take Timberwolf Trail.'
    },
    'lift-2': {
        name: 'Lift Two',
        type: 'lift',
        status: 'Open',
        description: 'Your primary access to the front side trails, back side, and all the best terrain. This quad is the most popular lift on the mountain, providing quick access to a variety of trails. For a gentle descent from the top, the Timberwolf Trail is your go-to option.'
    },
    'lift-3': {
        name: 'Lift Three',
        type: 'lift',
        status: 'Open',
        description: 'Accesses the southeastern front trails, easy back side access through Sleepy Hollow, and the thrilling Wolf Ridge race course. This quad is a favorite for experienced riders and racers alike. For a relaxing descent, take the Timberwolf Trail. If you\'re looking for acces to our back side trails, this lift offers the most convenient access.'
    },
    'lift-4': {
        name: 'Lift Four',
        type: 'lift',
        status: 'Open',
        description: 'Your first step to becoming a confident skier or snowboarder. This two-seater lift serves the dedicated learning area, where most beginner lessons take place. Enjoy the gentle slopes of Little Beaver beginner run as you hone your skills.'
    },
    'lift-5': {
        name: 'Lift Five',
        type: 'lift',
        status: 'Open',
        description: 'Located at the base of Birch Coulee and Little Crow, and halfway down Sleepy Hollow, Lift Five provides easy access to both trails. It\'s also one of two lifts that will transport you back to the front side, making it a valuable resource for navigating the mountain.'
    },
    'lift-6': {
        name: 'Lift Six',
        type: 'lift',
        status: 'Open',
        description: 'Your gateway to the heart of Mount Kato\'s intermediate terrain. Explore the scenic Big Hawk Ridge, Little Forest, and Sleepy Creek Cutoff trails, or access Birch Coulee through Birch Pass. While there are no beginner runs that extend to the bottom, Big Hawk Ridge offers a gentle introduction to intermediate terrain and is beloved by many regulars.'
    },
    'lift-7': {
        name: 'Lift Seven',
        type: 'lift',
        status: 'Open',
        description: 'Your sun-soaked sanctuary for afternoon adventures. A favorite among regulars, Lift Seven offers prime conditions when shadows descend on the front side. With stunning sunsets and access to Little Crow, Tommahawk Chute, and Big Bear, this lift is perfect for experienced riders seeking thrilling challenges. Please note, there are no easy trails from the top, so it\'s best suited for those who have mastered the basics.'
    },
    'lift-8': {
        name: 'Lift Eight',
        type: 'lift',
        status: 'Open',
        description: 'As our longest lift, Eight offers breathtaking views and convenient access to the front side and the chalet. Accessible from all back trails, it\'s the primary route back to the main area. If Eight is not running, Lift Five can get you back via Sleepy Creek Cutoff from Lift Six or Little Crow from Lift Seven. For the easiest descent, take the Timberwolf Trail.'
    },
    'ski-conveyor': {
        name: 'Ski Conveyor',
        type: 'lift',
        status: 'Open',
        description: 'SunKid Conveyor Lift: Your first step on the snow. Not quite ready for the chairlifts? No worries! Our SunKid conveyor lift is the perfect starting point for those new to skiing and snowboarding. It\'s ideal for our Kato Minis program and anyone else embarking on their winter sports journey. Located in the heart of our learning area on Little Beaver, our main beginner run, the SunKid makes learning a breeze.'
    },
    'tub-conveyor': {
        name: 'Tubing Conveyor',
        type: 'lift',
        status: 'Open',
        description: 'The tubing conveyor lift effortlessly takes you and your tube back to the top of the tubing hill, so you can enjoy another thrilling ride down without the hassle of a long climb. It\'s part of the fun and makes the tubing park accessible for all ages.'
    },
    'chalet-btn': {
        name: 'Chalet',
        type: 'facility',
        description: 'The Chalet is the central hub of Mount Kato. Located conveniently at the base of the mountain, it offers food and beverages, restrooms, and a place to relax and warm up. It\'s also where you\'ll find the Learning Center and is the main gathering spot for groups and families.'
    },
    'ski-patrol-btn': {
        name: 'Ski Patrol',
        type: 'facility',
        description: 'The Ski Patrol Aid Room at Mount Kato is located in the first building you encounter, right in front of Lift #1. It is conveniently situated next to the seasonal lockers and is easily identifiable by signage indicating "Ski Patrol."  If you are injured or need assistance, please do not hesitate to visit the Ski Patrol Aid Room for help.'
    },
    'tech-shop-btn': {
        name: 'Tech Shop',
        type: 'facility',
        description: 'The Tech Shop at Mount Kato is located on the main floor of the chalet, towards the east end of the building. It offers a wide range of services, including equipment tuning, waxing, and repairs. In addition, the Tech Shop carries a variety of accessories such as helmets, goggles, gloves, and many other items essential for a great day on the slopes.'
    },
    'ticket-windows-btn': {
        name: 'Ticket Windows',
        type: 'facility',
        description: 'Lift Tickets, Equipment Rental Forms & Snow Tubing Passes are all available at the ticket windows on east side of the Guest Services Building. Tickets and Passes can also be purchased online.'
    },
    'guest-services-btn': {
        name: 'Guest Services',
        type: 'facility',
        description: 'The Guest Services office at Mount Kato is located in the same office as the Ticket Windows. Use the entrence at the side of the building facing the slopes. The phone number for the Guest Services office is 507-625-3363.'
    },
    'rental-btn': {
        name: 'Rental',
        type: 'facility',
        description: 'The Rental shop is located just east of the Chalet, two buildings down from The Guest Services office. Enter the rental bulding at the first door on the southwest corner of the rental building (the side facing the hill). There are counters available to fill out your rental forms. There is also a scale and ruler available to help those that don\'t know their height or weight.'
    },
    'learning-center-btn': {
        name: 'Learning Center',
        type: 'facility',
        description: 'The Learning Center at Mount Kato is conveniently located on the first floor of the chalet, providing easy access for all guests. This dedicated space offers a welcoming environment for beginners and those looking to improve their skiing or snowboarding skills. The Learning Center provides a variety of programs and lessons for all ages and abilities, taught by experienced and certified instructors.'
    }
};

// DOM elements
const svgMap = document.getElementById('svg-map');
const infoName = document.getElementById('info-name');
const infoDifficulty = document.getElementById('info-difficulty');
const infoStatus = document.getElementById('info-status');
const infoDescription = document.getElementById('info-description');
const legendList = document.getElementById('legend-list');
const facilitiesList = document.getElementById('facilities-list');
const messageBox = document.getElementById('message-box');

let lastHighlightedElement = null;

// Function to display a temporary message
function showMessage(text) {
    messageBox.textContent = text;
    messageBox.classList.add('show');
    setTimeout(() => {
        messageBox.classList.remove('show');
    }, 2000);
}

// Function to update the info panel with trail data
function updateInfoPanel(elementId) {
    const data = trailData[elementId];
    if (data) {
        infoName.textContent = data.name;
        infoDescription.textContent = data.description;
        infoStatus.textContent = data.status ? `Status: ${data.status}` : '';
        infoDifficulty.textContent = data.difficulty ? `Difficulty: ${data.difficulty}` : '';
    } else {
        infoName.textContent = 'Select a trail, lift or facility to see details';
        infoDifficulty.textContent = '';
        infoStatus.textContent = '';
        infoDescription.textContent = '';
    }
}

// Function to highlight an element on the map
function highlightElement(element) {
    // Remove highlight from the previously highlighted element
    if (lastHighlightedElement) {
        lastHighlightedElement.classList.remove('is-highlighted');
        const legendItem = document.querySelector(`[data-element-id="${lastHighlightedElement.id}"]`);
        if (legendItem) {
            legendItem.classList.remove('font-bold', 'text-blue-300');
        }
    }
    // Add highlight to the current element
    if (element) {
        element.classList.add('is-highlighted');
        lastHighlightedElement = element;
        const legendItem = document.querySelector(`[data-element-id="${element.id}"]`);
        if (legendItem) {
            legendItem.classList.add('font-bold', 'text-blue-300');
        }
    }
}

// Event listener for clicks on the SVG map (event delegation)
svgMap.addEventListener('click', (event) => {
    let element = event.target.closest('.trail, .lift, .facility, [id$="-btn"]');
    if (element) {
        // If it's a button, find the corresponding trail/lift/facility path to highlight
        if(element.id.endsWith('-btn')) {
             element = document.querySelector(`[id^="${element.id.replace('-btn','')}_"]`) || document.getElementById(element.id.replace('-btn',''));
        }
        if (element) {
            updateInfoPanel(element.id);
            highlightElement(element);
            showMessage(`${trailData[element.id].name} selected!`);
        }
    } else {
        updateInfoPanel(null); // Clear the panel
        highlightElement(null); // Clear the highlight
    }
});

// Event listeners for mouseover on interactive elements
svgMap.addEventListener('mouseover', (event) => {
    let element = event.target.closest('.trail, .lift, .facility, [id$="-btn"]');
    if (element) {
        // Find the corresponding element path to highlight
        let elementToHighlight = element;
        if(element.id.endsWith('-btn')) {
             elementToHighlight = document.querySelector(`[id^="${element.id.replace('-btn','')}_"]`) || document.getElementById(element.id.replace('-btn',''));
        }

        if (elementToHighlight && elementToHighlight !== lastHighlightedElement) {
            elementToHighlight.classList.add('is-highlighted');
        }
    }
});

// Event listener for mouseout on interactive elements
svgMap.addEventListener('mouseout', (event) => {
    let element = event.target.closest('.trail, .lift, .facility, [id$="-btn"]');
    if (element) {
        // Find the corresponding element path to de-highlight
        let elementToDehighlight = element;
        if(element.id.endsWith('-btn')) {
             elementToDehighlight = document.querySelector(`[id^="${element.id.replace('-btn','')}_"]`) || document.getElementById(element.id.replace('-btn',''));
        }
        if (elementToDehighlight && elementToDehighlight !== lastHighlightedElement) {
            elementToDehighlight.classList.remove('is-highlighted');
        }
    }
});

// Event listener for clicks on the legend
function handleLegendClick(event) {
    const legendItem = event.target.closest('li');
    if (legendItem) {
        const elementId = legendItem.dataset.elementId;
        const element = document.getElementById(elementId);
        if (element) {
            updateInfoPanel(elementId);
            highlightElement(element);
            showMessage(`${trailData[elementId].name} selected!`);
        }
    }
}
if (legendList) {
    legendList.addEventListener('click', handleLegendClick);
}
if (facilitiesList) {
    facilitiesList.addEventListener('click', handleLegendClick);
}

// Initialize the app by generating the legend
function initializeLegend() {
    for (const id in trailData) {
        const data = trailData[id];
        const li = document.createElement('li');
        li.setAttribute('data-element-id', id);
        li.classList.add('cursor-pointer', 'hover:text-blue-400', 'flex', 'items-center', 'gap-2');

        // Add a color-coded dot or icon
        let colorClass;
        let icon = '';
        if (data.type === 'trail') {
            colorClass = data.difficulty.toLowerCase();
            li.classList.add(colorClass);
            icon = ``;
        } else if (data.type === 'lift') {
            colorClass = 'lift';
            li.classList.add(colorClass);
            icon = ``;
        } else if (data.type === 'facility') {
            colorClass = 'facility';
            li.classList.add(colorClass);
            icon = ``;
        }

        li.innerHTML = `${icon} ${data.name} ${data.difficulty ? `(${data.difficulty})` : ''}`;

        if (data.type === 'facility') {
            facilitiesList.appendChild(li);
        } else {
            legendList.appendChild(li);
        }
    }
}

// Initial setup on window load
window.onload = function() {
    initializeLegend();
    updateInfoPanel(null); // Set initial info panel text
    // Add custom classes to SVG paths for styling
    const trailElements = document.querySelectorAll('[id^="lift-"] path, [id^="lift-"] polyline, [id^="lift-"] rect');
    trailElements.forEach(el => {
        if (el.id.includes('lift-') && !el.classList.contains('lift')) {
            el.classList.add('lift');
            el.classList.add('interactive-element');
        }
    });

    const trails = document.querySelectorAll('#base-map .st22, #base-map .st21, #base-map .st23');
    trails.forEach(el => {
        if (el.id.includes('big-hawk-ridge') || el.id.includes('little-forest') || el.id.includes('sleepy-creek-cutoff') || el.id.includes('little-crow') || el.id.includes('wild-deer_00000111175242014020337350000005314294622917763735_') || el.id.includes('eagle-ridge_00000105411912884984635460000000851272969317083542_') || el.id.includes('sundance_00000123423080703862362750000018395771185093280954_') || el.id.includes('wolf-ridge_00000012461332066008056230000013452901512709310848_')) {
            el.classList.add('medium');
        } else if (el.id.includes('sleepy-hollow') || el.id.includes('birch-pass') || el.id.includes('birch-coulee') || el.id.includes('little-beave') || el.id.includes('timberwolf-trail_00000165211796375202709210000010540445799561181585_')) {
             el.classList.add('easy');
        } else if (el.id.includes('wolf-chute_00000086654002596323647540000008348298261282703253_') || el.id.includes('big-brave_00000120557085615029559250000003498223768255235244_') || el.id.includes('brave-chute_00000162324572142955322400000008528502739943837625_') || el.id.includes('little-brave_00000053518113907445259450000017414086792017273220_') || el.id.includes('tommahawk-chute') || el.id.includes('big-bear')) {
             el.classList.add('hard');
        }
        if (el.classList.contains('easy') || el.classList.contains('medium') || el.classList.contains('hard')) {
            el.classList.add('interactive-element');
            el.classList.add('trail');
        }
    });

    const facilities = document.querySelectorAll('[id$="-btn"]');
    facilities.forEach(el => {
        el.classList.add('interactive-element');
        el.classList.add('facility');
    });
};
